\begin{corollary}[High girth and chromatic number]\label{cor:high-girth-high-chromatic}
For all positive integers \(q,g\), there is a finite simple graph of girth
greater than \(g\) and chromatic number greater than \(q\).
\end{corollary}

\begin{lemma}[CCO inheritance on an actual fibre]\label{lem:fibreCCO}
The induced structure on $X_q$ is homogeneous, triangle-defined and
satisfies semantic homomorphic CCO.
\end{lemma}

\begin{lemma}[Bipartiteness of each atom graph]\label{lem:bip}
If $F$ is a finite symmetric complete atomic structure satisfying
semantic homomorphic CCO, then for every diversity atom $a$, the
simple graph $(F,a)$ is bipartite.
\end{lemma}

\begin{corollary}\label{cor:twogroup}
If $F$ is finite with semantic homomorphic CCO, then $\Aut(F)$ is a
finite $2$-group.
\end{corollary}

\begin{corollary}[Finite Hasse index two]\label{cor:hasse}
If $F$ is finite, transitive and has semantic homomorphic CCO, then
for any Hasse cover $U<V$ of invariant equivalences on $F$,
$[V:U]=2$.
\end{corollary}

\begin{theorem}[Joint homogeneity of all exact quotient sorts]
\label{thm:joint-exact}
Every finite binary partial isomorphism of $M_{\mathcal E}$ is induced
by an automorphism of $M$. This statement concerns arbitrary finite
collections of real and exact imaginary elements \emph{simultaneously}.
\end{theorem}

\begin{theorem}[Full exact rigid-bridge groupoid]
\label{thm:foundational-rigid-groupoid}
Starting with one $(a_*,K_*)$ and closing under bridges, converse
and composition gives a \emph{finite connected groupoid} of
full exact quotient-functional correspondences, with:
\begin{enumerate}[label=(\roman*),leftmargin=*]
\item the target kernel $K_b$ determined by $b$, independently
of which bridge path was used;
\item full exact arrows $R:a\to b$ with
$K_aR=R=RK_b$, $RR^\smile=K_a$,
$R^\smile R=K_b$, inducing actual equivariant bijections
$M_a/K_a\to M_b/K_b$;
\item elementary abelian $2$-groups as isotropy groups,
with each nonempty hom-set a torsor under either endpoint group;
\item freeness: two different arrows $a\to b$ cannot agree
at even one quotient point.
\end{enumerate}
No finite-index parity pivot or distinguished phase is assumed.
\end{theorem}

\begin{theorem}[Finite Hasse indices in the full invariant lattice]
\label{thm:full-relative-Hasse}
Every finite-relative-index cover $E\prec F$ in the \emph{full}
lattice of invariant equivalences of $M$ has $[F:E]=2$.
Consequently every finite relative index $[F:E]$ (not necessarily
covering) is a power of two.
\end{theorem}

\begin{lemma}[Relative exact closure separation]
\label{lem:ep-relative-K-closure}
Let $K$ be a full exact invariant equivalence on $M$. Let
$A,B$ be nonempty symmetric full exact $K$-bisaturated relations
containing $K$, and suppose $A\cap B=K$. Their stabilized
represented equivalence closures satisfy
\[
 \boxed{\langle A\rangle\cap\langle B\rangle=K.}
 \tag{S2}\label{eq:ep-relative-K-closure}
\]
Here $\langle A\rangle$ denotes the stable power of $A$;
this convention includes $K$ as the zeroth power.
\end{lemma}

\begin{theorem}[Class Helly, distributivity and CRT]
\label{thm:abstract-exact-crt}
Let $X$ be nonempty and $\mathcal E$ a sublattice of equivalences
on $X$ which pairwise commute under represented composition.  The
following are equivalent:
\begin{enumerate}
\item $\mathcal E$ is distributive;
\item every finite pairwise-intersecting family of classes of relations
      from $\mathcal E$ has nonempty total intersection;
\item for every finite nonempty family $E_1,\ldots,E_m\in\mathcal E$,
      the natural map
\[
 X/\bigcap_i E_i\longrightarrow\prod_i X/E_i
\]
      identifies the source bijectively with the tuples whose images
      agree in all quotients $X/(E_i\vee E_j)$.
\end{enumerate}
\end{theorem}

\begin{lemma}[Relative finite-index identity]\label{lem:crossingindex}
Let $E$ be as in Proposition~\ref{prop:minimalcut} and put $H=E\cap F$.
If $J\le K$ and $[K:J]<\infty$, then
\begin{align}
 K\cap(E\vee J)&=K\cap(H\vee J),\label{eq:crossing-intersect}\\
 [K:J]&=[E\vee K:E\vee J]\,[E\cap K:E\cap J].
    \label{eq:crossing-index}
\end{align}
If $E\cap J<E\cap K$, then $E\cap K\le H$.
For every $J$ one also has
\begin{equation}\label{eq:sigma-crossing}
 \Sigma(J)\cap(E\vee J)=J\vee H.
\end{equation}
\end{lemma}

\begin{remark}[Scope]\label{rem:packet-scope}
The assertions above establish the packet bottom, the actual minimal infinite cut (which may equal $\Top$), and the lattice identities.  They \emph{do not} construct the
conditional-bijection groupoid, prove relative real closure, or show
that a mixed typed quotient is automatically a new transitive CCO
source.  Those are separate obligations of the forthcoming chapters.
\end{remark}

\begin{lemma}[Relative separator]\label{lem:rh-separator}
Suppose $R$ is a global equivalence support and $P\subseteq\mathcal D$
is finite with $\bigcap_{p\in P}A_p\subseteq R$. If $u,v$ belong to
different $R$-orbits, then some $p\in P$ satisfies
$H(p,u)\cap H(p,v)=\varnothing$.
\end{lemma}

\begin{lemma}[Spoke fixedness]\label{lem:rh-spokefixed}
If $R$ is exact for $Z$, every $p_i$ is $R$-fixed.
\end{lemma}

\begin{lemma}[Even-walk classes]\label{lem:rh-evenwalk}
The $E_{B(p)}$-classes are precisely the even-$p$-walk connectivity
classes within a $p$-component. Thus
$[\Gamma(p):B(p)]\le2$. If $r\in L\cap\Gamma(p)$, then
$r\in B(p)$.
\end{lemma}

\begin{theorem}[Residual real closure over named owners]
\label{thm:relative-real-closure}
For every finite $A\subseteq N_B$ one has
\begin{equation}\label{eq:full-owner-acl}
 \operatorname{acl}_{N_B}(A)=
 \operatorname{acl}^{\rm eq}_{M}(A\cup B)\cap N_B=F[A].
\end{equation}
Moreover $F[A]$ is definable in $N_B$ from $A$ via the
literal named thin neighbour translations.
\end{theorem}

\begin{lemma}[Unary-or-binary pair coverage implies irreducibility]
\label{lem:typed-unary-binary-irreducibility}
Let $A$ be a finite induced unary-closed structure, with total unary
functions and relations of arbitrary finite arity. Suppose that for every
pair of distinct vertices $x,y\in A$, at least one of the following holds:
\begin{enumerate}[label=(\roman*)]
\item $x\in\cl_A\{y\}$;
\item $y\in\cl_A\{x\}$;
\item a positive named binary relation contains $(x,y)$ or $(y,x)$.
\end{enumerate}
Then $A$ is irreducible with respect to free amalgamation of induced
unary-closed substructures. In particular, a complete binary orbital
signature makes every completed member irreducible. The same holds if
some unary graph orbitals are represented only by their named functions,
provided every remaining pair satisfies (iii).
\end{lemma}

\begin{lemma}[Typed strong PC walk formula]
\label{lem:typed-PC-walk-formula}
Assume every $D^\infty_G(x,y)$ is NONEMPTY.
Then for each pair of distinct source vertices
\[
 \boxed{D^\infty_G(x,y)=
  \bigcap\{\Prof(w_P):P\text{ a specified SIMPLE
   }x\text{--}y\text{ path of }G\}.}
\]
The empty family gives the full typed diversity palette.
Every path word uses its ACTUAL typed intermediate sorts.
\end{lemma}

\begin{definition}[Original multiplication-closed filters]
\label{def:typed-filter}
A \emph{current family} $\mathcal J=(\mathcal J_{ij})$ is a
converse-closed subfamily of $\mathcal H$ containing all singleton
atomic menus and downward closed \emph{relative to the original exact
family}: if $D\in\mathcal J_{ij}$ and
$E\in\mathcal H_{ij}$ with $\varnothing\ne E\subseteq D$,
then $E\in\mathcal J_{ij}$.  A \emph{filter family}
$\mathfrak F=(\mathfrak F_{ij})$ is a (possibly empty) tagged
subfamily of the \emph{original} exact menus, closed under converse
and all compatible left and right products by members of
$\mathcal H$.  Its \emph{relative visibility} on $\mathcal J$ is
\begin{equation}\label{eq:relative-visibility}
 \begin{gathered}
 D\in\mathcal J_{ij},\quad A,B\in\mathfrak F_{ij},
 \quad A\cap D\ne\varnothing,\ B\cap D\ne\varnothing\\
 \Longrightarrow A\cap B\ne\varnothing.
 \end{gathered}
\end{equation}
Given such a filter, define the gate on $D\in\mathcal J_{ij}$ by
\begin{equation}\label{eq:typed-gate}
 \mathcal G(D)=D\cap\bigcap\{A\in\mathfrak F_{ij}:
                                    A\cap D\ne\varnothing\}.
\end{equation}
The empty active list leaves $D$ unchanged; no intersections of
menus from different hom-palettes are formed.
\end{definition}

\begin{lemma}[The bilateral-support implication]
\label{lem:typed-bilateral}
Suppose $\mathfrak F$ is multiplication/converse closed and has
relative visibility on $\mathcal J$.  For
$D\in\mathcal J_{ij}$, $E\in\mathcal J_{kj}$ and a fixed
$P\in\mathcal H_{ik}$, assume the two \emph{original} inclusions
\begin{equation}\label{eq:typed-bilateral-assumption}
 D\subseteq P*E,\qquad E\subseteq\bar P*D.
\end{equation}
Then the gate from \eqref{eq:typed-gate} preserves both:
\begin{equation}\label{eq:typed-bilateral-conclusion}
 \mathcal G(D)\subseteq P*\mathcal G(E),\qquad
 \mathcal G(E)\subseteq\bar P*\mathcal G(D).
\end{equation}
The symmetric assertion for a fixed \emph{right} factor follows by
converse.  There is no assumption that $P$ belongs to the current
family $\mathcal J$.
\end{lemma}

\begin{lemma}[Primitive loop saturation]\label{lem:covariant-loop-full}
In the full-owner transversal, for every nonempty loop exact
menu $W\in\mathcal H_{ss}$ one has
$W^{*n}=P_{ss}$ for all sufficiently large $n$.  Every compatible
nonempty exact menu absorbs a full palette on either side.
\end{lemma}

\begin{theorem}[Pure-owner covariant joint hereditary selector]
\label{thm:covariant-HS}
The full strong exact menu families of $U_B$ admit one joint
hereditary selector $h$ preserving converse, all three PC
coordinates, and survivor heredity, and satisfying
\begin{equation}\label{eq:covariant-HS}
        h_{\gamma s,\gamma t}(D)=h_{st}(D)
       \qquad(\gamma\in\Gamma).
\end{equation}
\end{theorem}

\begin{proposition}[Moving-type rectangular readings]
\label{prop:moving-readings}
The families $h^g$ are conservative, survivor-hereditary and
converse-compatible, are pure-owner $\Gamma$-covariant, and
obey the switching identity
\begin{equation}\label{eq:reading-switch}
    h^{u+v}_{vs,t}(vD)=v\,h^u_{st}(D).
\end{equation}
Moreover, if $D\in\mathcal H_{st}$, $A\in\mathcal H_{tu}$,
$P\in\mathcal H_{su}$ form a PC triple, then for
\emph{independently} chosen $g,k,\ell\in G$ their selections
form a legal fine-colour triangle:
\begin{equation}\label{eq:reading-rectangular}
   T\bigl(h^g_{st}(D),h^k_{tu}(A),h^\ell_{su}(P)\bigr).
\end{equation}
No distinctness of the sort labels is assumed.  The three
formal vertices of the triangle remain distinct even when their
owner labels coincide.
\end{proposition}

\begin{corollary}[Exact fixed-base lifting]\label{cor:fixed-base}
For an actual exact quotient $\pi_E:X\to X/E$ with
$\Age(X)$ having EPPA, all the compatible finite-base
requirements of Lemma~\ref{lem:finite-base} have a common witness.
\end{corollary}

\begin{theorem}[Completable HKN packet reservoir]
\label{thm:completable-reservoir}
There exists a finite $\Gamma$-structure $B_0\supseteq A$, in the
language of named owner predicates, original fine binary colours
and unary functions $t_g$ ($g\in G$), such that:
\begin{enumerate}
\item every point belongs to a unique literal regular full
      $G$-packet, with exactly one owner label at each point;
\item each requested partial map of $A$ with its compatible owner
      language component $\gamma\in\Gamma$ extends to a
      $\Gamma$-automorphism of $B_0$;
\item each pair of distinct packets has either a complete recorded
      fine matrix of colours outside $F$, or no recorded interpacket
      edges;
\item the entire partial structure $B_0$ has an actual
      \emph{injective} completion $C_0$ in $N$ fixing $A$;
\item every irreducible substructure of $B_0$ is carried into
      $A$ by one $\Gamma$-automorphism of the partial structure
      $B_0$ (irreducible-structure faithfulness).
\end{enumerate}
No compatibility of the choice $C_0$ with the $\Gamma$-action is
required.  In particular, the missing interpacket edges of $B_0$
are \emph{not} filled in permanently before the later valuation
construction.
\end{theorem}

\begin{lemma}[Origin-transversal reduction]
\label{lem:packet-origins}
Choose an origin $o_i$ for each full packet $\Pi_i$ in such a
diagram and put $\beta_i=\operatorname{own}(o_i)\in B$.  For each
recorded pair let $c_{ij}=\col(o_i,o_j)\notin F$; the whole
matrix is required to be
\begin{equation}\label{eq:packet-matrix}
 \col(t_g o_i,t_h o_j)=(g+h)c_{ij}\qquad(g,h\in G).
\end{equation}
Form a partial typed diagram on the indices $i$, with sort
$\beta_i$ and edge $c_{ij}$ exactly for recorded packet pairs.
An injective typed completion of this \emph{origin transversal}
in $U_B$ lifts to an injective completion of the entire recorded
packet diagram in $N$, preserving a complete embedded source base
up to its unique named-owner isomorphism.
\end{lemma}

\begin{lemma}[PC gauge and pure-owner naturality]
\label{lem:R07-PC-gauge}
The greatest nonempty PC fixed family commutes with all the
independent origin shifts~\eqref{eq:R07-gauge} and with any
pure owner-language permutation $\gamma\in\Gamma$.  More
precisely, for distinct $p,r,q$, typed menus $A_{pr},B_{rq}$ satisfy
\begin{equation}\label{eq:R07-gauge-product}
 ((\delta_p+\delta_r)A_{pr})*((\delta_r+\delta_q)B_{rq})
 =(\delta_p+\delta_q)(A_{pr}*B_{rq}),
\end{equation}
with the \emph{moved endpoint owner types}; the same transport
commutes with intersections and converse.
\end{lemma}

\begin{lemma}[Naturality under arbitrary full-row lifts]
\label{lem:R07-domain-covariance}
Let $\alpha_C$ be a map~\eqref{eq:R07-lift}, and denote by
$\pi_C(p)=(\sigma i,f')$ its induced permutation of actual
packets.  For all vertices $x,y$ in distinct actual packets,
\begin{equation}\label{eq:R07-raw-domain-invariance}
  D_{\alpha_Cx,\alpha_Cy}=D_{xy}
\end{equation}
as \emph{raw fine-colour sets}; their endpoint owner types
are related by the pure permutation $\gamma$.
\end{lemma}

\begin{lemma}[The full palette is closed-strong]
\label{lem:acf-full-palette}
For every standing homogeneous source $M$, the full diversity
palette $S=\mathcal D(M)$ strongly amalgamates spans of finite
\emph{real-algebraically-closed} induced structures.
\end{lemma}

\begin{corollary}[Ordinary EPPA for symmetric binary CCO]
\label{thm:main-ordinary-eppa}
The age of every standing symmetric binary AP+semantic
homomorphic CCO structure has ordinary EPPA.
\end{corollary}

\begin{corollary}[Closed and vertex-transitive finite witnesses]
\label{cor:acf-closed-transitive}
For every nonempty original input, the witness built in the
preceding phased proof can additionally be chosen
\emph{real-algebraically closed in $M$ and vertex-transitive}.
\end{corollary}

\begin{theorem}[AP Ramsey expansion, relative to A108 and V27]\label{thm:ramsey-general-ap}
The class $\Age(Q)$ has a reasonable, reduct-surjective, precompact Ramsey
expansion by finitely many unary and binary relations.
\end{theorem}

\begin{lemma}[Clone-stable terminalisation]\label{lem:ramsey-clone-stability}
The safe unary splits of V27 yield
$M^\dagger=Q^\dagger\times\NN$, where $Q^\dagger$ is a reasonable finite
unary expansion of $Q$. Every nonempty terminal sort of $Q^\dagger$ is
infinite. In each corresponding clone sort $s$, $K_s$ is proper and exact.
\end{lemma}

\begin{lemma}[Quantifier-free tuple domain]\label{lem:ramsey-mi-domain}
For $b_i\in B_{s,J_{s,i}}$, the tuple $(b_i)_i$ represents one old
$Q_s^\dagger$ point if and only if
\begin{equation}\label{eq:ramsey-domain}
                 c_s\in\Spec(b_i,b_j)\quad(i<j).
\end{equation}
This condition is quantifier-free in the existing binary hidden language.
\end{lemma}

\begin{lemma}[Singleton fine-colour reconstruction]\label{lem:ramsey-singleton-recovery}
Let $q,r$ be distinct old points of terminal sorts $s,t$ and let $a$ be their
original typed fine colour. For their compatible coordinate tuples,
\begin{equation}\label{eq:ramsey-singleton}
 \bigcap_{i,j}\Spec\bigl(\eta_s(q)_i,\eta_t(r)_j\bigr)=\{a\}.
\end{equation}
In particular every original fine colour is quantifier-free definable on
valid tuples using the hidden binary shadows and equality.
\end{lemma}

\begin{lemma}[Templates and all embeddings]\label{lem:ramsey-template-bijection}
The codes determine the generated hidden support $h(A^*)$ up to a unique
isomorphism over the root coordinates. For every $D\in\HH$,
\begin{equation}\label{eq:ramsey-embeddings}
       \Emb_{\KK}(A^*,N(D))\ \cong\ \Emb_{\HH}(h(A^*),D).
\end{equation}
\end{lemma}

\begin{corollary}[A smaller visible signature]\label{cor:ramsey-small-language}
In the concrete application one can retain only the original fine colours,
the safe terminal unary labels, and finitely many coordinate-term order
comparisons. After fixed hidden-sort block normalisation, comparisons between
different hidden target sorts can also be omitted.
\end{corollary}

\begin{theorem}[Exact trace product]
\label{thm:ep-trace-product}
Let \(D:s\to t\) and \(E:t\to w\) be nonempty old exact domains.
For children \(u,v,z\) over \(s,t,w\) suppose both
\(\operatorname{tr}_{uv}(D)\) and
\(\operatorname{tr}_{vz}(E)\) are nonempty. Then
\[
 \boxed{\ 
 \operatorname{tr}_{uv}(D)\ ;
 \operatorname{tr}_{vz}(E)
   =\operatorname{tr}_{uz}(D;E).\
 }\tag{TP}\label{eq:ep-tp}
\]
This is equality of actual relations, not just of nonempty
endpoint colour sets.
\end{theorem}

\begin{lemma}[No bipartite atom on a terminal diagonal]
\label{lem:ep-bp-loopless}
For \(a\in\mathrm{BP}\) and any \(t\in T\), one has
\((t,t)\notin R_a\).
\end{lemma}

\begin{assumption}[Terminal infinite-cover hypothesis]\label{ass:standing}
In addition to Assumption~\ref{ass:general}, assume
\begin{enumerate}[label=(A\arabic*),start=4]
\item \label{A:cover} on EACH current named transitive real sort $M_a$, every strict
      cover in its full lattice of invariant equivalence relations has
      infinite relative index, including covers whose upper endpoint is
      the universal equivalence on that sort.
\end{enumerate}
We call this the \emph{terminal} or \emph{sortwise infinite-cover branch}.
\end{assumption}

\begin{lemma}[Totality of the lifted phase product]
\label{lem:phase-totality}
Every compatible pair of allowed lifted atomic pair types has an output with
the required xor of endpoint phase differences.
\end{lemma}

\begin{theorem}[Typed exact phase primality]
\label{thm:typed-epp}
Let $P_1,\ldots,P_m\subseteq\mathcal T^{ab}$ be reachable profiles between
component sorts.  If
\[
 \varnothing\ne\bigcap_iP_i\subseteq B_{ab}^{\delta},
\tag{8}\label{eq:epp-hyp}
\]
then $P_j\subseteq B_{ab}^{\delta}$ for some $j$.
\end{theorem}

\begin{proposition}[Typed point-generated coordinate SAP]
\label{prop:typed-coordinate-sap}
Full point-generated coordinate expansions in the transition-enriched hidden
language have strong amalgamation over full point-generated common
substructures.
\end{proposition}

\begin{theorem}[Typed strong hidden amalgamation]
\label{thm:typed-hidden-sap}
The transition-enriched typed hereditary hidden envelope has strong
amalgamation.
\end{theorem}

\begin{lemma}[Rigidity of completed typed hidden structures]
\label{lem:typed-hidden-rigidity}
Every homomorphism between completed members of the transition-enriched typed
hidden envelope is an embedding.
\end{lemma}

\begin{theorem}[General SAP symmetric CCO Ramsey expansion]
\label{thm:internal-v27-general-ramsey}
Every homogeneous triangle-defined complete finite symmetric binary
SAP+homomorphic-CCO age has a finite relational precompact Ramsey expansion.
\end{theorem}
